      const spB = splitNote(rawB);
      const noteB = sid ? Notes.get(sid) || spB.note : spB.note;
      const mA = (cObj?.voteState?.voted && cObj?.voteState?.modelAName && !/^(未知|待定|Model A)$/i.test(cObj.voteState.modelAName))
