setInterval(() => { if (!(typeof document !== 'undefined' && document.hidden)) Titles.tick(); }, 5000);

// ---------- 对话框（Electron 不支持 window.prompt，用自己的输入框）----------
const Dialog = {
  open(build) {
    document.querySelectorAll('.dlg-back:not(.anc-gh)').forEach(x => x.remove());
    return new Promise(res => {
      const back = h('div', { class: 'dlg-back' }), box = h('div', { class: 'dlg', role: 'dialog' });
      const done = v => { back.remove(); removeEventListener('keydown', key, true); res(v); };
      const key = e => { if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); done(null); } };
      addEventListener('keydown', key, true);
      back.addEventListener('pointerdown', e => { if (e.target === back) done(null); });
      build(box, done); back.append(box); document.body.append(back);
      setTimeout(() => (box.querySelector('input,textarea') || box.querySelector('.btn'))?.focus(), 30);
    });
  },
  // 输入：返回字符串（可能为空）或 null（取消）
  ask({ title, value = '', placeholder = '', hint = '', ok = '保存', max = 60, extra = null }) {
    return this.open((box, done) => {
      const inp = h('input', { class: 'dlg-in', value, placeholder, maxlength: String(max), onkeydown: e => { if (e.key === 'Enter' && !e.isComposing) { e.preventDefault(); done(inp.value); } } });
      const cnt = h('span', { class: 'dim' }), upd = () => { cnt.textContent = inp.value.length + ' / ' + max; if (preview) preview.textContent = extra(inp.value); };
      const preview = extra ? h('div', { class: 'dlg-prev mono' }) : null;
      inp.addEventListener('input', upd);
      box.append(h('div', { class: 'dlg-t' }, title), hint ? h('div', { class: 'dlg-h' }, hint) : null, inp, preview,
        h('div', { class: 'dlg-row' }, cnt, h('span', { class: 'grow' }), h('button', { class: 'btn ghost', onclick: () => done(null) }, '取消'), h('button', { class: 'btn', onclick: () => done(inp.value) }, ok)));
      upd(); setTimeout(() => { inp.focus(); inp.select(); }, 40);
    });
  },
  confirm({ title, text = '', ok = '确定', danger = false, body = null }) {
    return this.open((box, done) => {
      box.append(h('div', { class: 'dlg-t' }, title), text ? h('div', { class: 'dlg-h' }, text) : document.createDocumentFragment(), body || document.createDocumentFragment(),
        h('div', { class: 'dlg-row' }, h('span', { class: 'grow' }), h('button', { class: 'btn ghost', onclick: () => done(false) }, '取消'), h('button', { class: 'btn' + (danger ? ' danger' : ''), onclick: () => done(true) }, ok)));
    }).then(v => !!v);
  },
};

// 删除对话：云端删除 + 清掉本机的模型信息 / 备注 / 运行记录 / 标签页
async function deleteChat(e) {
  const sid = String(e?.id || '').trim();
  if (!sid) return false;
  if (typeof FingerprintBatch !== 'undefined' && FingerprintBatch.owns?.(sid)) {
    toast('该对话在批量指纹队列中，请先停止测试', 'err');
    return false;
  }
  const v = Titles.view(sid, e.title), name = v.note || v.model || e.title || '这个对话';
  const ok = await Dialog.confirm({ title: '删除对话', text: `删除「${name}」？\n会同时删除 Brana 上的对话和本机保存的模型信息、备注、运行记录，无法恢复。`, ok: '删除', danger: true });
  if (!ok) return false;
  const isEval = Boolean(e?.type === 'evaluation' || e?.mode === 'battle' || e?.mode === 'direct' || (typeof Chats !== 'undefined' && Chats.get?.(sid)?.isEvaluation));
  const isLocalRec = Boolean(e?._localRecovered);
  // 乐观即时移除：确认后 0ms 从左侧列表、缓存与打开的标签页彻底移除，绝不等待慢速多路由协议请求卡住卡片
  forget(sid);
  toast('已删除');
  if (!sid.startsWith('pending:') && !sid.startsWith('local-')) {
    void History.remove(sid, { isEval }).catch(err => {
      if (err?.status !== 404 && !isLocalRec) {
        try {
          if (typeof Store !== 'undefined') {
            const q = Store.get('archDelQ', []);
            if (Array.isArray(q) && !q.includes(sid)) Store.set('archDelQ', [...q, sid]);
          }
          if (typeof Bulk !== 'undefined' && !Bulk.running?.('del')) {
            setTimeout(() => { try { Bulk.resume?.(); } catch {} }, 2500);
          }
        } catch {}
      }
    });
  }
  return true;
}
/* 本机按对话保存的缓存，一个入口清：
   删除 → 全清（型号 / 备注 / 收藏 / 推理分账本 / 鹈鹕结果 / 花费明细 / 消息缓存 / 运行记录 / 待发队列）；
   归档 → 只清大块和临时的（消息缓存、运行记录、待发队列），型号 / 备注 / 收藏 / 推理分留着——归档列表要靠它们分类和搜索。
   鹈鹕测试图、指纹库样本按型号 / 全局保存，不属于某一个对话，不在这里清。 */
const LocalCache = {
  drop(ids, { archived = false } = {}) {
    const list = [...new Set([...ids].filter(Boolean))]; if (!list.length) return 0;
    for (const sid of list) {
      try { MsgCache.del(sid); } catch {}
      try { Trace.clear(sid); } catch {}
    }
    try { Drafts.dropChats(list); } catch {}
    if (archived) return list.length;
    let dm = false, dt = false;
    for (const sid of list) {
      if (Models.all[sid]) { delete Models.all[sid]; dm = true; }
      if (typeof AcctStats !== 'undefined' && AcctStats.turns && AcctStats.turns[sid]) { delete AcctStats.turns[sid]; dt = true; }
      try { Fav.setQuiet?.(sid, false); } catch {}
    }
    try { Notes.dropMany ? Notes.dropMany(list) : list.forEach(sid => Notes.drop(sid)); } catch {}
    if (dm) { if (typeof Models !== 'undefined' && Models.save) Models.save(); else Store.set('models', Models.all); }
    if (dt) try { AcctStats.save?.(); } catch {}
    try { Strength.bookDrop(list); } catch {}
    try { PelicanTest.drop(list); } catch {}
    try { Budget.drop(list); } catch {}
    return list.length;
  },
};
function forget(sid) {
  const sKey = String(sid || '').trim();
  if (!sKey) return;
  try { LocalCache.drop([sKey]); } catch {}
  try {
    if (typeof History !== 'undefined') {
      History.items = (History.items || []).filter(x => x && String(x.id) !== sKey);
      History._ix = null;
      History.markDeleted?.([sKey]);
      History.bury?.([sKey]);
      History.saveSoon?.();
    }
  } catch {}
  try { if (typeof ArchiveHistory !== 'undefined') ArchiveHistory.drop([sKey]); } catch {}
  try { if (typeof CardSelect !== 'undefined' && CardSelect.ids?.delete(sKey)) CardSelect.revision++; } catch {}
  try { if (typeof Fav !== 'undefined' && Fav.setQuiet) Fav.setQuiet(sKey, false); } catch {}
  try { if (typeof Titles !== 'undefined') { Titles.prio?.delete?.(sKey); Titles._viewMemo?.delete?.(sKey); } } catch {}
  try {
    const c = typeof Chats !== 'undefined' ? Chats.get(sKey) : null;
    if (c) {
      try { c.ctl?.abort(); } catch {}
      try { c._loadCtl?.abort(); } catch {}
      Chats.delete(sKey);
    }
  } catch {}
  try {
    if (typeof Tabs !== 'undefined' && Array.isArray(Tabs.list)) {
      for (const t of Tabs.list.filter(x => x && x.sid === sKey)) {
        try { Tabs.close(t.key); } catch {}
      }
    }
  } catch {}
  try {
    if (typeof Models !== 'undefined' && Models.all?.[sKey]) {
      delete Models.all[sKey];
      if (Models.save) Models.save(); else Store.set('models', Models.all);
      try { Bus.emit('models', sKey); } catch {}
    }
  } catch {}
  try { Notes.drop(sKey); } catch {}
  try { Trace.clear(sKey); } catch {}
  try { AcctStats.report(); } catch { try { AcctStats.soon(150); } catch {} }
  try {
    if (typeof UI !== 'undefined') {
      UI._cards?.delete?.(sKey);
      const listEl = typeof document !== 'undefined' ? document.querySelector('#list') : null;
      if (listEl) {
        for (const child of [...listEl.children]) {
          if (child?.dataset?.sid === sKey) child.remove();
        }
      }
      UI.renderList?.(true);
      UI.renderTabs?.();
    }
  } catch {}
}

// ---------- 自动识别：打开对话后，1 小时内有运行记录的自动读取模型信息 / Trace（不用手动点）----------
const AutoId = {
  busy: new Set(),
  async run(chat) {
    if (this.busy.has(chat.sid)) return; this.busy.add(chat.sid); Dock.soon?.();
    try { await this.run1(chat); } finally { this.busy.delete(chat.sid); Dock.soon?.(); }
  },
  async run1(chat) {
    const sid = chat.sid, e = History.byId(sid);
    if (chat?.isEvaluation || chat?.evalMode === 'battle' || chat?.evalMode === 'direct' || e?.type === 'evaluation') return;
    if (typeof BillingProbe !== 'undefined' && typeof BillingProbe.automatic === 'function') {
      try { BillingProbe.automatic(chat); } catch {}
    }
    const at = Date.parse(String(e?.updatedAt || '').replace(' ', 'T').replace(/\+00$/, 'Z'));
    if (Number.isFinite(at) && now() - at > 65 * 60000 && !chat.busy) return;   // 运行令牌 1 小时后失效，读不到
    if (typeof ReadLimit !== 'undefined' && ReadLimit.active?.() && !chat.token) return;
    const needTrace = !Trace.turns(sid).length || (Trace.latest(sid)?.at || 0) < at - 60000;
    const needModel = !Models.get(sid) || Models.get(sid).partial;
    let discoveredZero = false;
    try {
      if (needTrace && Prefs.traceAuto !== false) {
        let n = Trace.validRuns(sid).length;
        if (!n) {
          n = await Trace.discover(chat);
          if (!n) discoveredZero = true;
        }
        if (n) await Trace.sync(sid, { deep: true });
      }
    } catch {}
    if (!discoveredZero && (!Models.get(sid) || Models.get(sid).partial) && needModel && !chat.identifying && !chat.busy) chat.identifyOld();
  },
};
